window.AULAS = window.AULAS || {};
window.AULAS["aula-07-1"] = {"id": "aula-07-1", "titulo": "Aula 7.1 - Semiologia osteomioarticular I", "subtitulo": "Ombro, cotovelo, punho e mão: exame, manobras e síntese", "pdf": "pdf/aula-07-1.pdf", "fontes": ["Aula 7.1 (slides do Prof. Dr. João Vítor Galo Esteves, versão atualizada com 41 slides)", "Rocco, Semiologia Médica, 2ª ed. (figuras 11.12, 11.13 e 11.16, citadas nos slides)", "Bickley, Bates Propedêutica Médica (figura 23.27, citada no slide 31)"], "resumo": [{"titulo": "1. Abertura e competências (slides 2 e 3)", "pontos": [{"t": "Ponto de partida (slide 2)", "sub": ["A queixa de dor não define imediatamente a estrutura acometida: pode ser articulação, tendão ou dor referida.", "O raciocínio exige método: localizar, caracterizar, examinar e integrar.", "Foco inicial: avaliação de sintomas e membros superiores.", "Erro comum: assumir que o local exato apontado pelo paciente é a origem estrutural anatômica do problema."]}, {"t": "O que o estudante deverá conseguir fazer (slide 3)", "sub": ["Parte I: mão e ombro (membros superiores). Parte II: coluna, joelho e pé.", "Caracterizar sintomas e sua distribuição topográfica.", "Executar exame regional sistemático e reprodutível.", "Demonstrar as principais manobras indicadas.", "Descrever achados e reconhecer os limites do exame clínico."]}]}, {"titulo": "2. A história: dor, padrão e rigidez (slides 4 a 6)", "pontos": [{"t": "Dor: localizar e qualificar (slide 4)", "sub": ["Localização e irradiação: focal, difusa, profunda ou com trajeto radiante.", "Início e evolução: súbito ou gradual; constante ou intermitente.", "Dinâmica: relação estrita com movimento ativo, passivo e repouso.", "Contexto: trauma prévio, sobrecarga recente, recorrência de episódios.", "Atenção: dor irradiada não é automaticamente radiculopatia; dor no ombro pode vir da coluna cervical, e dor no joelho pode ser dor referida do quadril."]}, {"t": "Padrão mecânico e padrão inflamatório (slide 5)", "sub": ["Mecânico: uso e carga mecânica agravam frequentemente a queixa; melhora ou alívio com o repouso; sinais vitais e inflamatórios locais ausentes.", "Inflamatório: repouso pode agravar (por exemplo, dor noturna que desperta o paciente); rigidez matinal prolongada favorece a suspeita de inflamação; calor e sinovite reforçam o diagnóstico.", "Nota do slide: são tendências clínicas, não critérios diagnósticos absolutos.", "Erro comum: ignorar a sobreposição. A osteoartrite pode apresentar sinovite reativa, e inflamações sistêmicas também doem com a carga. A interpretação exige integração clínica."]}, {"t": "Rigidez: tempo e contexto importam (slide 6)", "sub": ["No gráfico do slide, a rigidez mecânica é breve (desaparece em cerca de 30 minutos) e a inflamatória é prolongada (continua ao longo dos 60 minutos).", "Traduza o sintoma: o que significa 'travado'? Resistência articular, bloqueio mecânico súbito ou fraqueza verdadeira?", "Tempo: a rigidez ocorre ao despertar ou apenas após longo repouso?", "Duração: quantifique o tempo exato em minutos.", "Evolução: compare a sensação antes e após iniciar a movimentação."]}]}, {"titulo": "3. Artralgia, artrite e aumento de volume (slides 7 e 9)", "pontos": [{"t": "Artralgia não é sinônimo de artrite (slide 7)", "sub": ["Artralgia: dor subjetiva percebida na articulação; ausência de alterações anatômicas no exame.", "Artrite: inflamação articular objetiva (sinal objetivo e palpável).", "O que pesquisar: espessamento sinovial, derrame intra-articular e calor local.", "Dor periarticular exige delimitação topográfica estrita (não diagnosticar como artrite).", "Atenção: o rubor pode estar ausente. É o sinal flogístico menos frequente; não dependa da vermelhidão para diagnosticar uma artrite profunda."]}, {"t": "Aumento de volume: o que está aumentado (slide 9)", "sub": ["Derrame: líquido livre intra-articular (identificado por flutuação).", "Sinovite: espessamento sinovial (consistência borrachuda ou esponjosa).", "Bursite: aumento estritamente localizado, superficial e extra-articular.", "Proliferação óssea: consistência pétrea e endurecida (por exemplo, nódulos de Heberden).", "Edema: sinal do cacifo positivo, acometimento subcutâneo, distribuição frequentemente gravitacional."]}]}, {"titulo": "4. Distribuição, função e sistema (slides 8, 10 e 11)", "pontos": [{"t": "Distribuição e evolução do acometimento (slide 8)", "sub": ["Contagem: monoarticular (1); oligoarticular (2 a 4); poliarticular (5 ou mais).", "Eixo: padrão axial versus padrão periférico.", "Simetria: simétrico versus assimétrico (exige comparação exata da articulação homóloga).", "Evolução no tempo: persistente, aditivo (soma-se), migratório (pula de articulação) ou puramente episódico."]}, {"t": "Função: o paciente consegue realizar o movimento? (slide 10)", "sub": ["Atividades do slide: pentear o cabelo, abrir um frasco ou pote, levantar de uma cadeira, subir um degrau.", "A intensidade relatada da dor não substitui a repercussão funcional.", "Membros superiores: avaliar capacidade de vestir-se, pentear-se, alcançar objetos altos, segurar, pinçar e abrir tampas.", "Membros inferiores e eixo: avaliar marcha, sentar, levantar e subir escadas.", "O examinador deve isolar se o impedimento é causado por dor, fraqueza verdadeira ou instabilidade articular estrutural."]}, {"t": "A queixa articular pode ser sistêmica (slide 11)", "sub": ["A avaliação sistêmica é mandatória em quadros inflamatórios, poliarticulares ou persistentes.", "Sintomas gerais: febre de origem obscura, perda ponderal, fadiga inexplicável.", "Pele e anexos: erupções cutâneas, alterações ungueais, fenômeno de Raynaud.", "Mucosas e órgãos: uveíte ou olho vermelho doloroso, queixas gastrointestinais ou uretrais.", "Atenção sistêmica: sinais sistêmicos alteram imediatamente a prioridade diagnóstica. Investigue essas associações com foco clínico, sem transformar a consulta em um interrogatório genérico."]}]}, {"titulo": "5. Segurança e método do exame (slides 12 a 16)", "pontos": [{"t": "Segurança antes das manobras (slide 12)", "sub": ["Explique passo a passo e obtenha concordância explícita do paciente.", "Exponha a região adequadamente, garantindo privacidade.", "Inicie o exame sempre pelo lado ou região menos doloroso.", "Em traumas recentes ou deformidades evidentes, a cautela é mandatória.", "Fluxo do slide: avaliação inicial (história e inspeção). Exame tolerável: progressão para o método sistematizado. Trauma com deformidade ou déficit neurovascular: red flag, avaliação prioritária, contraindicado estresse ou testes provocativos.", "Nota: um exame interrompido por dor deve ser documentado como limitado, e não como negativo."]}, {"t": "O método que se repete em cada região (slide 13)", "sub": ["Seis etapas: 1) inspeção; 2) palpação; 3) mobilidade ativa; 4) mobilidade passiva; 5) força (paresia versus inibição); 6) testes especiais (provocação e estabilidade).", "A sistematização cria um hábito automático e evita omissões críticas.", "Não confunda as etapas: inspecione antes de tocar, palpe antes de mover.", "Testes especiais são selecionados pela hipótese, não executados ao acaso."]}, {"t": "Palpação: localizar antes de interpretar (slide 14)", "sub": ["Estruturas-alvo: diferencie interlinha articular, tendão, bursa e êntese.", "Sinais cardinais: temperatura comparativa (use o dorso das mãos); consistência e flutuação (distinção entre líquido e proliferação sinovial).", "Mapeamento: distinga dor focal pontual de dor difusa ou inflamatória.", "Dica clínica: palpar uma área dolorosa não demonstra, por si, inflamação exclusiva daquela estrutura. Relacione o achado à mobilidade e à função."]}, {"t": "Mobilidade ativa, passiva e contrarresistência (slide 15)", "sub": ["Ativa: o paciente executa o movimento de forma independente. Passiva: o examinador conduz o segmento relaxado. Resistida: contração isométrica contra resistência externa imposta.", "Ativa menor que passiva: investigar lesão tendínea, fraqueza neurológica ou inibição por dor aguda.", "Ambas limitadas: sugere forte componente articular ou capsular mecânico."]}, {"t": "Força: paresia ou inibição pela dor (slide 16)", "sub": ["Observe atrofias de trofismo e simetria muscular prévia; teste grupos musculares comparáveis bilateralmente; estabilize rigorosamente o segmento proximal.", "Gradue a força apenas quando o teste for considerado válido.", "Escala MRC: 0 nenhuma contração; 1 contração sem movimento; 2 movimento com gravidade eliminada; 3 vence a gravidade; 4 vence resistência submáxima; 5 força normal.", "Alerta: um teste interrompido por dor aguda isolada não permite classificar o músculo como parético. Relate a inibição."]}]}, {"titulo": "6. Registro do teste positivo (slide 17)", "pontos": [{"t": "Um teste positivo precisa ser descrito", "sub": ["Qual sintoma exato foi reproduzido?", "Em qual local anatômico e em qual fase do movimento?", "Houve dor, sensação de fraqueza ou frouxidão articular mecânica?", "Como o achado se compara com o lado oposto assintomático?", "Registro vago: 'Teste de Jobe positivo. Ombro ruim'.", "Registro descritivo: 'Manobra de Jobe reproduz dor anterolateral habitual no arco final de elevação, sem redução evidente de força sustentada. Lado oposto livre'."]}]}, {"titulo": "7. Ombro: exame básico e arco doloroso (slides 18 a 20)", "pontos": [{"t": "Exame básico antes dos testes (slide 18)", "sub": ["Inspeção: avalie contornos, trofismo e simetria nas vistas anterior, lateral e posterior; observe o ritmo escapulotorácico.", "Palpação: percorra sistematicamente a articulação acromioclavicular (AC), os tubérculos úmerais e o processo coracoide.", "Mobilidade: compare arcos de elevação e rotações (interna e externa) bilateralmente.", "Apenas avance para manobras especiais (epônimos) após mapear a função básica.", "Alerta do slide: um teste interrompido por dor aguda isolada não permite classificar o músculo como parético. Relate a inibição."]}, {"t": "Pesquisa do arco doloroso (slide 19)", "sub": ["Paciente em ortostase ou sentado com tronco ereto; abdução ativa, de forma lenta e progressiva.", "Pergunte exatamente o ponto de início e término do sintoma doloroso no trajeto.", "Dor restrita ao arco intermediário sugere pinçamento de estruturas no espaço subacromial (impacto subacromial).", "Dor no arco final extremo sugere patologia da articulação acromioclavicular."]}, {"t": "Manobra de Neer (slide 20)", "sub": ["Bloqueio: impeça o movimento escapular estabilizando a escápula com firmeza superior.", "Extensão: mantenha o cotovelo do paciente completamente estendido.", "Provocação: eleve passivamente o braço em flexão anterior máxima com leve rotação interna, de forma contínua, lenta e controlada.", "Interpretação: positivo quando a dor habitual é reproduzida pelo pinçamento estrutural da grande tuberosidade contra o arco coracoacromial."]}]}, {"titulo": "8. Ombro: Hawkins, sequência e testes do manguito (slides 21 a 29)", "pontos": [{"t": "Manobra de Hawkins (slide 21)", "sub": ["Posicionamento: eleve o ombro em flexão de 90 graus e mantenha o cotovelo fletido a 90 graus.", "Fulcro: estabilize ativamente o braço (úmero) apoiando o cotovelo do paciente.", "Provocação: rotação interna passiva, forçando o antebraço para baixo como uma alavanca; verifique se reproduz a dor subacromial habitual.", "Síntese clínica: nenhum teste especial de ombro possui sensibilidade ou especificidade absolutas isoladamente. Integre a história clínica ao somatório dos achados (Neer, Hawkins e arco doloroso)."]}, {"t": "A sequência precede os epônimos (slide 23)", "sub": ["Um teste especial não substitui a avaliação básica. Executar todos os testes conhecidos indiscriminadamente gera falsos positivos e confusão diagnóstica.", "1) Inspeção: contorno, trofismo e postura. 2) Palpação: topografia precisa da dor e temperatura. 3) Mobilidade: comparação ativa versus passiva (diferencia restrição articular de dor muscular). 4) Força resistida: integridade do sistema contrátil. 5) Testes especiais: aplicados apenas para testar a hipótese anatômica já formulada."]}, {"t": "Supraespinhoso: teste de Jobe (slide 24)", "sub": ["Posição: braços elevados a 90 graus no plano escapular (aproximadamente 30 graus à frente do plano frontal), polegares apontados para baixo.", "Ação: o examinador aplica resistência gradual para baixo; o paciente tenta manter a sustentação.", "Alerta: diferencie dor de fraqueza. Dor e incapacidade de sustentar o braço não são a mesma coisa; a inibição dolorosa pode simular paresia. Registre a dor e a força separadamente."]}, {"t": "Infraespinhoso: teste de Patte (slide 25)", "sub": ["Posição: ombro abduzido a 90 graus e cotovelo fletido a 90 graus.", "Ação: o paciente mantém o esforço em rotação externa enquanto o examinador oferece resistência na porção distal do antebraço (forçando rotação interna).", "Alerta: compensação biomecânica. Observe o tronco; o paciente frequentemente tenta compensar a fraqueza ou a dor do infraespinhoso girando ou inclinando o tórax."]}, {"t": "Subescapular: teste de Gerber (slide 26)", "sub": ["Posição: dorso da mão apoiado sobre a região lombar (rotação interna e extensão).", "Ação: solicite ao paciente que afaste ativamente a mão das costas, vencendo a gravidade ou resistência.", "Falso positivo por rigidez: a impossibilidade de posicionar o membro por dor intensa ou rigidez capsular não equivale a fraqueza do subescapular. O teste torna-se inadequado ou inconclusivo.", "Erro comum: extensão compensatória do cotovelo para afastar a mão."]}, {"t": "Tendão bicipital: teste de Speed (slide 27)", "sub": ["Posição: cotovelo perfeitamente estendido, antebraço supinado (palma para cima).", "Ação: elevação anterior contra a resistência do examinador; a outra mão deve palpar ativamente o sulco bicipital.", "Topografia exata: o achado positivo é a dor focal ao longo da porção longa do bíceps (corredeira bicipital). Desconforto difuso no ombro não deve receber automaticamente a mesma interpretação."]}, {"t": "Compressão acromioclavicular: adução cruzada (slide 28)", "sub": ["Posição: braço elevado à frente em 90 graus.", "Ação: o examinador conduz a adução horizontal de forma controlada, cruzando o braço sobre o tórax do paciente.", "Dor de alongamento versus compressão: dor pontual na articulação acromioclavicular sustenta a hipótese. Dor na face posterior do ombro durante o movimento representa alongamento capsular ou muscular, não uma patologia da articulação AC."]}, {"t": "Síntese: diagnóstico topográfico do ombro (slide 29)", "sub": ["Supraespinhoso: Jobe; dor ou queda na abdução no plano escapular; pitfall: confundir inibição dolorosa com paresia verdadeira.", "Infraespinhoso: Patte; perda de força na rotação externa; pitfall: rotação compensatória do tronco.", "Subescapular: Gerber; incapacidade de afastar o dorso da mão da lombar; pitfall: limitação técnica por rigidez capsular.", "Tendão bicipital: Speed; dor focal no sulco bicipital; pitfall: aceitar dor difusa como positividade.", "Articulação acromioclavicular: adução cruzada; dor focal superior; pitfall: interpretar dor posterior por alongamento como compressão."]}]}, {"titulo": "9. Cotovelo, punho e mão (slides 30 a 35)", "pontos": [{"t": "Cotovelo: inspeção, palpação e mobilidade (slide 30)", "sub": ["Inspeção: observe as faces anterior e posterior; busque perda de contornos articulares normais ou aumento de volume na fossa olecraniana.", "Palpação estruturada: epicôndilo lateral, epicôndilo medial e olécrano.", "Mobilidade: teste flexão (135 graus), extensão (menos de 10 graus), pronação e supinação, de forma comparativa.", "Bursa versus articulação: tumefação superficial posterior sobre o olécrano sugere bursite. Alterações articulares verdadeiras reduzem a mobilidade passiva e obliteram os sulcos entre os epicôndilos e o olécrano."]}, {"t": "Epicôndilo lateral: teste de Cozen (slide 31)", "sub": ["Posição: cotovelo fletido e apoiado; antebraço pronado e mão fechada (punho cerrado).", "Ação: o paciente realiza extensão do punho contra a resistência do examinador.", "Estabilização: uma mão do examinador apoia o cotovelo e palpa ativamente o epicôndilo lateral durante o movimento.", "Localização restrita: a positividade exige reprodução da dor focada na origem extensora lateral. Dor sentida no próprio punho não indica epicondilopatia."]}, {"t": "Epicôndilo medial: flexão do punho resistida (slide 32)", "sub": ["Posição: antebraço supinado e apoiado.", "Ação: flexão do punho contra a resistência do examinador.", "Estabilização: segurar o segmento proximal e palpar a origem flexora medial.", "Red flag neurológica: dor focal sugere acometimento flexor medial. Porém, queixas de parestesia irradiada para o 4º e 5º dedos exigem avaliação do nervo ulnar. Não rotule irritação ulnar como epicondilite apenas pela proximidade."]}, {"t": "Síntese biomecânica: articular versus periarticular (slide 33)", "sub": ["A comparação entre mobilidade ativa e passiva é a chave para localizar a restrição estrutural antes de aplicar testes provocativos.", "Doença articular verdadeira (ex.: osteoartrite): limitação simétrica em ambos os movimentos; restrição mecânica ou capsular.", "Doença periarticular (ex.: tendinopatia): mobilidade ativa limitada pela dor; mobilidade passiva preservada; estrutura articular íntegra."]}, {"t": "Punho e mãos: estrutura e função (slide 34)", "sub": ["O exame das mãos deve priorizar o repertório funcional.", "Inspeção sistemática do dorso, da palma, das unhas e das atrofias (tenar e hipotenar).", "Teste flexão, extensão, desvios e fechamento completo.", "Funções dinâmicas do slide: pinça, oposição e fechamento."]}, {"t": "Mãos: diferenciação de nódulos e tumefação (slide 35)", "sub": ["Sinovite (inflamatório): tumefação amolecida, elástica ou flutuante (derrame ou proliferação sinovial); topografia frequente em metacarpofalangianas (MCF) e interfalangianas proximais (IFP); quadro clínico: artropatias inflamatórias crônicas (ex.: artrite reumatoide).", "Proliferação óssea (degenerativo): nodulações rígidas e duras (osteófitos); nódulos de Heberden nas interfalangianas distais (IFD) e nódulos de Bouchard nas interfalangianas proximais (IFP); quadro clínico: osteoartrite."]}]}, {"titulo": "10. Armadilhas e testes do punho (slides 36 a 39)", "pontos": [{"t": "Checklist crítico: evitando armadilhas semiológicas (slide 36)", "sub": ["Inibição não é paralisia: nunca classifique a força muscular (grau 0-5) como deficitária se a manobra estiver limitada primariamente por dor intensa.", "Rigidez invalida testes específicos: testes de força em posições extremas (ex.: Gerber, Patte) são falsos-positivos ou inconclusivos se a articulação for mecanicamente rígida.", "Neurologia versus ortopedia: sintomas irradiados (parestesia, choque) no exame do ombro ou do cotovelo medial exigem investigação cervical e de compressão nervosa periférica (ex.: nervo ulnar).", "Palpação exige contexto: palpar uma área dolorosa não demonstra, por si só, a inflamação daquela estrutura; o achado deve ser relacionado à resposta de resistência contrátil."]}, {"t": "Punho: teste de Phalen (slide 37)", "sub": ["Flexione os punhos sem força excessiva e mantenha a posição por até 60 segundos.", "Observe o surgimento de parestesias habituais e localize rigorosamente o território sensitivo mediano.", "Alerta: dor local isolada no punho não confirma compressão. Teste negativo não exclui neuropatia periférica."]}, {"t": "Punho: sinal de Tinel (slide 38)", "sub": ["Percuta de leve, repetidamente, o nervo mediano no punho; ponto: borda radial do tendão palmar longo.", "Pergunte por formigamento nos dedos. Positivo: parestesia no território mediano.", "Alerta: dor local à percussão não é Tinel positivo. Nenhum dos dois testes (Phalen e Tinel), isolado, confirma ou exclui."]}, {"t": "De Quervain: técnica e nomenclatura (slide 39)", "sub": ["Avalie dor sobre o 1º compartimento dorsal e palpe a região do estiloide radial (foco de dor).", "Finkelstein é o teste correto (condução suave pelo examinador). Eichhoff é o erro comum: com o polegar aprisionado, tem alta taxa de falso positivo.", "Atenção: evite desvio ulnar forçado. Dor inespecífica não confirma tenossinovite."]}]}, {"titulo": "11. Síntese e caso integrador do ombro (slide 40)", "pontos": [{"t": "Integrando o ombro doloroso", "sub": ["Cartão de caso: paciente de 42 anos; queixa de dor ao elevar o braço após sobrecarga (trabalho acima da cabeça).", "Exame: arco intermediário doloroso; mobilidade passiva preservada; Jobe doloroso; força preservada.", "Localização: região periarticular ou subacromial. Padrão: dor mecânica relacionada a movimento específico.", "Exame básico: mobilidade passiva livre indica articulação íntegra.", "Interpretação: os testes indicam irritação do manguito, não comprovam rotura.", "Fim da Parte I."]}]}], "glossario": [{"termo": "Manobra de Neer", "epônimo": "Neer", "tecnica": "Elevação passiva do braço em flexão anterior máxima", "definicao": "Positivo quando reproduz a dor habitual por pinçamento subacromial.", "slide": 20}, {"termo": "Manobra de Hawkins (Hawkins-Kennedy)", "epônimo": "Hawkins", "tecnica": "Flexão de 90 graus e rotação interna passiva", "definicao": "Reproduz a dor subacromial habitual.", "slide": 21}, {"termo": "Teste de Jobe", "epônimo": "Jobe", "tecnica": "Braços a 90 graus no plano escapular, com resistência para baixo", "definicao": "Avalia o supraespinhoso. Dor ou queda na abdução no plano escapular.", "slide": 24}, {"termo": "Teste de Patte", "epônimo": "Patte", "tecnica": "Rotação externa resistida, ombro a 90 graus e cotovelo fletido", "definicao": "Avalia o infraespinhoso. Perda de força na rotação externa.", "slide": 25}, {"termo": "Teste de Gerber", "epônimo": "Gerber", "tecnica": "Dorso da mão apoiado na lombar; afastar a mão das costas", "definicao": "Avalia o subescapular. Incapacidade de afastar a mão sugere fraqueza, mas rigidez capsular invalida o teste.", "slide": 26}, {"termo": "Teste de Speed", "epônimo": "Speed", "tecnica": "Elevação anterior contra resistência, cotovelo estendido e antebraço supinado", "definicao": "Avalia o tendão do bíceps. Dor focal no sulco bicipital.", "slide": 27}, {"termo": "Teste de Cozen", "epônimo": "Cozen", "tecnica": "Extensão do punho contra resistência, cotovelo fletido", "definicao": "Avalia o epicôndilo lateral. Dor focada na origem extensora lateral.", "slide": 31}, {"termo": "Nódulos de Heberden", "epônimo": "Heberden", "tecnica": "Palpação da IFD", "definicao": "Nódulo ósseo duro na IFD, da osteoartrite.", "slide": 35}, {"termo": "Nódulos de Bouchard", "epônimo": "Bouchard", "tecnica": "Palpação da IFP", "definicao": "Nódulo ósseo na IFP, da osteoartrite.", "slide": 35}, {"termo": "Teste de Phalen", "epônimo": "Phalen", "tecnica": "Flexão dos punhos por até 60 segundos", "definicao": "Compressão do nervo mediano. Parestesia no território mediano.", "slide": 37}, {"termo": "Sinal de Tinel", "epônimo": "Tinel", "tecnica": "Percussão leve e repetida do nervo mediano no punho, na borda radial do tendão palmar longo", "definicao": "Positivo quando surge parestesia no território mediano. Dor local à percussão não é Tinel positivo; Tinel e Phalen, isolados, não confirmam nem excluem.", "slide": 38}, {"termo": "Teste de Finkelstein", "epônimo": "Finkelstein", "tecnica": "Desvio ulnar com polegar fletido sobre a palma, com condução suave", "definicao": "Avalia a tenossinovite de De Quervain, no primeiro compartimento dorsal.", "slide": 39}, {"termo": "Teste de Eichhoff", "epônimo": "Eichhoff", "tecnica": "Polegar aprisionado pelos dedos, com desvio ulnar", "definicao": "Erro comum para De Quervain, com alta taxa de falso positivo.", "slide": 39}], "manobras": [{"nome": "Exame básico do ombro (inspeção, palpação e mobilidade)", "epônimo": null, "como": "Inspecione contornos e ritmo escapulotorácico; palpe AC, tubérculos e coracoide; compare arcos de elevação e rotações.", "alterado": "Assimetria, dor palpatória focal, limitação de arco.", "significado": "Mapeia a função antes dos testes especiais.", "slide": 18}, {"nome": "Arco doloroso", "epônimo": null, "como": "Abdução ativa lenta, tronco ereto; registrar o início e o término da dor.", "alterado": "Dor no arco intermediário ou no arco final extremo.", "significado": "Pinçamento subacromial (intermediário) ou articulação AC (final).", "slide": 19}, {"nome": "Neer", "epônimo": "Neer", "como": "Estabilize a escápula; cotovelo estendido; elevação passiva em flexão com leve rotação interna.", "alterado": "Dor habitual reproduzida.", "significado": "Pinçamento da grande tuberosidade contra o arco coracoacromial.", "slide": 20}, {"nome": "Hawkins", "epônimo": "Hawkins", "como": "Ombro a 90 graus, cotovelo fletido a 90; rotação interna passiva.", "alterado": "Dor subacromial habitual reproduzida.", "significado": "Compõe o somatório com Neer e o arco doloroso.", "slide": 21}, {"nome": "Jobe", "epônimo": "Jobe", "como": "Braços a 90 graus no plano escapular, polegares para baixo; resistência para baixo.", "alterado": "Dor ou incapacidade de sustentação.", "significado": "Supraespinhoso. Distinga dor de fraqueza.", "slide": 24}, {"nome": "Patte", "epônimo": "Patte", "como": "Ombro a 90 graus, cotovelo a 90; rotação externa resistida no antebraço.", "alterado": "Perda de força na rotação externa.", "significado": "Infraespinhoso. Observe a compensação do tronco.", "slide": 25}, {"nome": "Gerber", "epônimo": "Gerber", "como": "Dorso da mão na lombar; afastar a mão das costas contra gravidade ou resistência.", "alterado": "Incapacidade de afastar a mão.", "significado": "Subescapular, se não houver rigidez capsular.", "slide": 26}, {"nome": "Speed", "epônimo": "Speed", "como": "Cotovelo estendido, antebraço supinado; elevação anterior contra resistência.", "alterado": "Dor focal no sulco bicipital.", "significado": "Tendinopatia da porção longa do bíceps.", "slide": 27}, {"nome": "Adução cruzada (AC)", "epônimo": null, "como": "Braço a 90 graus à frente; adução horizontal controlada.", "alterado": "Dor pontual na articulação AC.", "significado": "Patologia AC. Dor posterior por alongamento não é compressão.", "slide": 28}, {"nome": "Cozen", "epônimo": "Cozen", "como": "Extensão do punho contra resistência; palpe o epicôndilo lateral.", "alterado": "Dor focada na origem extensora lateral.", "significado": "Epicondilite lateral.", "slide": 31}, {"nome": "Flexão resistida do punho (epicôndilo medial)", "epônimo": null, "como": "Antebraço supinado; flexão do punho contra resistência.", "alterado": "Dor focal na origem flexora medial; parestesia no 4º e 5º dedos.", "significado": "Epicondilite medial; parestesia exige avaliação do nervo ulnar.", "slide": 32}, {"nome": "Phalen", "epônimo": "Phalen", "como": "Flexão dos punhos por até 60 segundos.", "alterado": "Parestesia no território mediano.", "significado": "Compressão do mediano. Negativo não exclui neuropatia.", "slide": 37}, {"nome": "Tinel", "epônimo": "Tinel", "como": "Percutir de leve, repetidamente, o nervo mediano no punho, na borda radial do tendão palmar longo.", "alterado": "Parestesia (formigamento) no território mediano.", "significado": "Sugere compressão do mediano. Dor local à percussão não é Tinel positivo; nenhum dos dois testes (Tinel e Phalen), isolado, confirma ou exclui.", "slide": 38}, {"nome": "Finkelstein (De Quervain)", "epônimo": "Finkelstein", "como": "Desvio ulnar do punho com polegar sob os dedos; condução suave.", "alterado": "Dor sobre o estiloide radial.", "significado": "Tenossinovite do primeiro compartimento dorsal.", "slide": 39}], "caso": {"titulo": "Casos integradores de ombro, cotovelo, punho e mão", "perfil": "Ombro doloroso, registro do teste positivo, cotovelo e nervo ulnar, armadilhas do punho, Tinel e Phalen, mãos, segurança e função.", "etapas": [{"titulo": "Etapa 1 · Ombro doloroso após sobrecarga (slides 19, 24 e 40)", "texto": "Paciente de 42 anos, pintor de tetos, com dor ao elevar o braço direito há 3 meses após sobrecarga no trabalho acima da cabeça. Sem trauma. Abdução ativa lenta: dor entre 60 e 120 graus, com retorno sem dor no arco final. Mobilidade passiva livre e força preservada.", "perguntas": [{"pergunta": "Qual é a interpretação topográfica da dor no arco intermediário?", "alternativas": ["Patologia acromioclavicular, pela dor no arco final extremo", "Pinçamento subacromial, pela dor no arco intermediário", "Radiculopatia cervical, pela irradiação ao antebraço", "Capsulite adesiva, pela restrição ativa e passiva global", "Artrose glenoumeral avançada, pela dor com carga axial"], "gabarito": "B", "justificativa": "Dor restrita ao arco intermediário (60 a 120 graus) sugere pinçamento subacromial; dor no arco final extremo sugere patologia acromioclavicular.", "erradas": {"A": "A dor acromioclavicular aparece no arco final extremo, perto de 180 graus.", "C": "Não há irradiação nem déficit sensitivo que sugiram raiz cervical.", "D": "A capsulite restringe também o movimento passivo, que aqui está livre.", "E": "A artrose glenoumeral limitaria o movimento passivo."}}, {"pergunta": "Qual é a conclusão sustentada pelo Jobe doloroso com força preservada e mobilidade passiva livre?", "alternativas": ["Ruptura completa do supraespinhoso, pela dor ao teste", "Fratura do úmero, pela dor intensa à elevação do braço", "Irritação do manguito, sem comprovar ruptura completa", "Lesão do subescapular, pelo teste de Jobe positivo", "Normalidade, pois o Jobe doloroso não tem valor clínico"], "gabarito": "C", "justificativa": "Os testes indicam irritação do manguito rotador, mas não comprovam ruptura; mobilidade passiva livre indica articulação íntegra e dor mecânica ligada ao movimento.", "erradas": {"A": "Ruptura completa exigiria fraqueza evidente, e a força está preservada.", "B": "Não há trauma que sustente fratura.", "D": "O Jobe avalia o supraespinhoso, e não o subescapular.", "E": "O Jobe doloroso tem valor, mas não comprova ruptura."}}]}, {"titulo": "Etapa 2 · Registro do teste positivo (slide 17)", "texto": "O residente escreve no prontuário apenas: 'Jobe positivo, ombro ruim'. O preceptor pede um registro que outro profissional consiga reproduzir.", "perguntas": [{"pergunta": "Qual registro atende ao padrão descritivo do material?", "alternativas": ["Jobe positivo, ombro ruim, sem descrever local nem fase do movimento", "Jobe negativo, sem queixas, sem descrever local nem fase do movimento", "Jobe: dor anterolateral habitual, força preservada, lado oposto livre", "Ombro com dor, sem especificar o teste nem o achado associado", "Paciente com fraqueza, sem comparar com o lado oposto e sem local"], "gabarito": "C", "justificativa": "O teste positivo deve descrever o sintoma reproduzido, o local, a fase do movimento, a presença de dor, fraqueza ou frouxidão e a comparação com o lado oposto.", "erradas": {"A": "O registro vago não informa sintoma, local nem fase.", "B": "O resultado contradiz o exame doloroso.", "D": "Ombro com dor não especifica teste nem achado.", "E": "A comparação com o lado oposto é parte obrigatória."}}, {"pergunta": "Qual erro de interpretação o Jobe com dor e força preservada ajuda a evitar?", "alternativas": ["Confundir dor com fraqueza, pois dor pode simular paresia", "Atribuir fraqueza ao subescapular em vez do supraespinhoso", "Interpretar a mobilidade passiva livre como lesão capsular", "Chamar de positivo qualquer movimento que dê rigidez matinal", "Registrar a dor como sinal de artrite inflamatória ativa"], "gabarito": "A", "justificativa": "Dor e incapacidade de sustentar não são a mesma coisa: a inibição dolorosa pode simular paresia, e dor e força devem ser registradas separadamente.", "erradas": {"B": "O subescapular é avaliado pelo Gerber.", "C": "Mobilidade passiva livre indica articulação íntegra.", "D": "O Jobe não avalia rigidez matinal.", "E": "O quadro é mecânico e relacionado ao movimento."}}]}, {"titulo": "Etapa 3 · Cotovelo e nervo ulnar (slides 31 e 32)", "texto": "Mulher de 55 anos, digitadora, com dor no lado lateral do cotovelo direito e parestesia no quarto e quinto dedos, pior à noite. O teste de Cozen reproduz dor focal no epicôndilo lateral. A flexão do punho resistida provoca parestesia irradiada ao dedo mínimo.", "perguntas": [{"pergunta": "Como interpretar os dois achados?", "alternativas": ["Epicondilite lateral, com parestesia explicada pela mesma lesão local", "Epicondilite lateral e possível neuropatia ulnar a avaliar", "Síndrome do túnel do carpo, pela parestesia noturna dos dedos", "Radiculopatia C6, pelo Cozen positivo e pela dor lateral", "Lesão do nervo radial, pela dor lateral do cotovelo e parestesia"], "gabarito": "B", "justificativa": "Dor focal no epicôndilo lateral sustenta epicondilite; parestesia do quarto e quinto dedos exige avaliação do nervo ulnar, sem rotular como epicondilite.", "erradas": {"A": "A parestesia ulnar não é explicada por epicondilite lateral.", "C": "O túnel do carpo cursa com parestesia mediana, e não ulnar.", "D": "O Cozen positivo é focal e não define raiz cervical.", "E": "A dor focal no epicôndilo lateral não indica neuropatia radial."}}]}, {"titulo": "Etapa 4 · Armadilhas do punho (slides 37 e 39)", "texto": "Homem de 48 anos, diabético, com parestesia noturna em polegar, indicador e médio e dor no lado radial do punho ao segurar objetos. No Phalen há parestesia mediana aos 40 segundos. O residente executou o Eichhoff, com o polegar preso, e achou 'positivo'.", "perguntas": [{"pergunta": "Qual é a interpretação mais precisa?", "alternativas": ["De Quervain confirmada pelo Eichhoff positivo, sem outro teste", "Compressão do mediano (Phalen); De Quervain exige Finkelstein", "Radiculopatia C6 bilateral, pela parestesia dos dedos radiais", "Artrite reumatoide do punho, pela dor no lado radial e rigidez", "Neuropatia ulnar, pelos dedos acometidos à noite e ao esforço"], "gabarito": "B", "justificativa": "Phalen positivo com parestesia mediana sugere compressão do mediano; o teste correto para De Quervain é o de Finkelstein, e o Eichhoff, com polegar aprisionado, tem alta taxa de falso positivo.", "erradas": {"A": "O Eichhoff é erro comum e não confirma De Quervain.", "C": "Não há dado de raiz cervical.", "D": "O quadro não descreve sinovite poliarticular.", "E": "O território é mediano, e não ulnar."}}, {"pergunta": "Quanto tempo o Phalen deve ser mantido, e o que um resultado negativo significa?", "alternativas": ["Até 60 segundos; teste negativo não exclui neuropatia", "Cinco minutos; teste negativo exclui compressão do mediano", "Dez segundos; teste negativo confirma túnel do carpo", "Trinta minutos; teste negativo exclui qualquer neuropatia", "Dois minutos; negativo confirma tenossinovite de De Quervain"], "gabarito": "A", "justificativa": "O Phalen mantém a flexão por até 60 segundos; dor local isolada no punho não confirma compressão e um teste negativo não exclui neuropatia periférica.", "erradas": {"B": "Cinco minutos é tempo excessivo, e negativo não exclui.", "C": "Dez segundos é curto, e negativo não confirma nada.", "D": "Trinta minutos não é aplicável.", "E": "O Phalen não avalia De Quervain."}}]}, {"titulo": "Etapa 5 · Tinel e Phalen na mesma paciente (slides 37 e 38)", "texto": "Mulher de 50 anos com formigamento noturno nos três primeiros dedos da mão direita. O Phalen reproduz parestesia mediana aos 45 segundos. Ao percutir o punho sobre o tendão palmar longo, ela refere apenas dor no ponto percutido, sem formigamento nos dedos.", "perguntas": [{"pergunta": "Como interpretar a percussão que provoca só dor local?", "alternativas": ["Tinel positivo, pois a dor reproduzida confirma o diagnóstico do túnel", "Não é Tinel positivo, pois só parestesia mediana vale como positiva", "Tinel negativo, e por isso a compressão do mediano está excluída", "Resultado inválido, pois o mediano só é percutido no meio da palma", "Positivo apenas se o paciente referir dor em todo o antebraço"], "gabarito": "B", "justificativa": "O Tinel é positivo quando a percussão leve do mediano no punho provoca parestesia no território mediano. Dor local à percussão não é Tinel positivo (slide 38).", "erradas": {"A": "Dor local à percussão não é Tinel positivo.", "C": "Nenhum dos testes, isolado, exclui a compressão.", "D": "O mediano é percutido no punho, na borda radial do tendão palmar longo.", "E": "O critério é parestesia no território mediano, e não dor."}}, {"pergunta": "Qual é a conclusão sobre Tinel e Phalen, usados isoladamente?", "alternativas": ["O Phalen positivo, isolado, confirma a compressão do mediano", "O Tinel negativo isolado exclui a neuropatia periférica do punho", "O Tinel positivo, isolado, exclui outras causas de parestesia", "Nenhum dos dois, isolado, confirma nem exclui a compressão", "Os dois testes só valem se mantidos por mais de dois minutos"], "gabarito": "D", "justificativa": "O slide 38 alerta que nenhum dos dois testes, isolado, confirma ou exclui; o slide 37 acrescenta que Phalen negativo não exclui neuropatia periférica.", "erradas": {"A": "Nenhum dos dois testes, isolado, confirma.", "B": "Teste negativo não exclui neuropatia periférica.", "C": "Outras causas de parestesia continuam possíveis.", "E": "O Phalen mantém a flexão por até 60 segundos."}}]}, {"titulo": "Etapa 6 · Mãos: sinovite ou osteófito (slides 34 e 35)", "texto": "Homem de 60 anos com nódulos duros e indolores nas interfalangianas distais das duas mãos, sem calor. Mulher de 38 anos com tumefação amolecida e elástica nas metacarpofalangianas e nas interfalangianas proximais.", "perguntas": [{"pergunta": "Qual é o achado e o padrão em cada paciente, na ordem apresentada?", "alternativas": ["Nódulos de Heberden, osteoartrite; sinovite, artropatia inflamatória", "Sinovite, artropatia inflamatória; nódulos de Heberden, osteoartrite", "Nódulos de Bouchard, osteoartrite; sinovite, osteoartrite degenerativa", "Edema com cacifo, insuficiência venosa; nódulos de Heberden, gota", "Bursite, processo extra-articular; derrame, osteoartrite mecânica"], "gabarito": "A", "justificativa": "Nodulações rígidas e duras nas IFD são nódulos de Heberden, da osteoartrite. Tumefação amolecida, elástica, em MCF e IFP é sinovite, de artropatia inflamatória crônica, como a artrite reumatoide (slide 35).", "erradas": {"B": "A ordem está invertida em relação aos pacientes.", "C": "Bouchard é na IFP; a sinovite é inflamatória, não degenerativa.", "D": "Edema com cacifo é subcutâneo e gravitacional, e o caso é de mãos.", "E": "Bursite é localizada e superficial, e o caso descreve nódulos duros."}}, {"pergunta": "O que o roteiro manda inspecionar no punho e na mão?", "alternativas": ["Só o dorso e a palma, deixando as unhas e as atrofias para depois", "Apenas as articulações dolorosas, sem comparar com a mão oposta", "Dorso, palma, unhas, atrofias tenar e hipotenar e função de pinça", "Somente a força de preensão, sem inspecionar a pele nem as unhas", "Exclusivamente as interfalangianas distais, por causa dos nódulos"], "gabarito": "C", "justificativa": "O slide 34 manda inspecionar dorso, palma, unhas e atrofias tenar e hipotenar, e testar flexão, extensão, desvios, fechamento, pinça e oposição.", "erradas": {"A": "O roteiro inclui unhas e atrofias.", "B": "A inspeção é sistemática, e não restrita ao ponto doloroso.", "D": "A força é só uma parte; a inspeção sistemática vem antes.", "E": "O exame percorre punho, MCF, IFP e IFD, além das estruturas."}}]}, {"titulo": "Etapa 7 · Segurança antes das manobras (slide 12)", "texto": "Homem de 30 anos, uma hora após queda de moto, com deformidade grosseira do antebraço e dormência nos dedos. O residente quer começar o exame pelos testes provocativos.", "perguntas": [{"pergunta": "Qual é a conduta adequada neste momento?", "alternativas": ["Iniciar pelos testes provocativos para confirmar a lesão óssea", "Aplicar o estresse articular para medir o grau de instabilidade", "Seguir o método sistematizado completo antes de qualquer decisão", "Comparar a força com o lado oposto, estressando a região lesada", "Red flag: avaliação prioritária, sem estresse nem provocação"], "gabarito": "E", "justificativa": "Trauma com deformidade ou déficit neurovascular é red flag: avaliação prioritária, e estresse e testes provocativos são contraindicados (slide 12).", "erradas": {"A": "Testes provocativos são contraindicados com deformidade e déficit.", "B": "O estresse é contraindicado neste cenário.", "C": "Este paciente sai do fluxo habitual e vai à avaliação prioritária.", "D": "Estressar a região lesada é o que o slide proíbe."}}, {"pergunta": "Como documentar um exame interrompido por dor intensa?", "alternativas": ["Como exame negativo, pois nenhum achado foi reproduzido", "Como exame limitado por dor, e não como exame negativo", "Como exame normal, pois o paciente não colaborou no teste", "Como músculo parético, pois a força não pôde ser graduada", "Como teste positivo, pois a dor impediu o movimento"], "gabarito": "B", "justificativa": "Um exame interrompido por dor deve ser documentado como limitado, e não como negativo (slide 12).", "erradas": {"A": "Exame interrompido não é negativo.", "C": "A interrupção por dor não torna o exame normal.", "D": "Teste interrompido por dor não classifica o músculo como parético.", "E": "A dor que interrompe não equivale a teste positivo."}}]}, {"titulo": "Etapa 8 · Função e queixa sistêmica (slides 10 e 11)", "texto": "Mulher de 45 anos com dor no ombro e dificuldade para pentear o cabelo e abrir potes. Há três meses tem olho vermelho doloroso, alteração nas unhas e fenômeno de Raynaud.", "perguntas": [{"pergunta": "Ao avaliar a função, o que o examinador deve isolar?", "alternativas": ["Somente a intensidade da dor relatada pelo paciente no momento", "Apenas se o paciente consegue andar sem auxílio durante a consulta", "Se o impedimento vem de dor, fraqueza verdadeira ou instabilidade", "Se há deformidade visível, sem considerar a repercussão funcional", "Apenas o grau de força do membro, pela escala de zero a cinco"], "gabarito": "C", "justificativa": "O examinador deve isolar se o impedimento é causado por dor, fraqueza verdadeira ou instabilidade articular estrutural (slide 10).", "erradas": {"A": "A intensidade da dor não substitui a repercussão funcional.", "B": "A função avaliada aqui é a do membro superior, em atividades como pentear.", "D": "A repercussão funcional é justamente o foco.", "E": "A força é uma parte; é preciso separar dor, fraqueza e instabilidade."}}, {"pergunta": "O que fazer com olho vermelho doloroso, unhas alteradas e Raynaud?", "alternativas": ["Tratar só o ombro, pois os achados extra-articulares são coincidência", "Atribuir tudo à sobrecarga do trabalho, sem ampliar a avaliação", "Ignorar os achados e solicitar apenas imagem do ombro doloroso", "Investigar a associação sistêmica com foco, pois muda a prioridade", "Transformar a consulta em um interrogatório genérico de todos os sistemas"], "gabarito": "D", "justificativa": "Sinais sistêmicos (olhos, pele e unhas, Raynaud) alteram imediatamente a prioridade. Investigue com foco clínico, sem transformar a consulta em interrogatório genérico (slide 11).", "erradas": {"A": "Sinais sistêmicos alteram a prioridade diagnóstica.", "B": "A queixa articular pode ser sistêmica; é preciso ampliar.", "C": "A imagem não substitui a investigação sistêmica dirigida.", "E": "O slide pede foco clínico, sem interrogatório genérico."}}]}]}, "imagens": [{"slide": 2, "titulo": "Parte I: examinar a queixa osteomioarticular", "explicacao": "A dor não define a estrutura (articulação, tendão ou dor referida). Localizar, caracterizar, examinar e integrar."}, {"slide": 3, "titulo": "Competências esperadas", "explicacao": "Parte I (mão e ombro) e Parte II (coluna, joelho e pé). Exame regional sistemático, manobras e descrição dos achados."}, {"slide": 4, "titulo": "Dor: localizar e qualificar", "explicacao": "Localização e irradiação, início e evolução, dinâmica e contexto. Dor irradiada não é radiculopatia automática."}, {"slide": 5, "titulo": "Padrão mecânico e inflamatório", "explicacao": "Mecânico: carga agrava, repouso alivia. Inflamatório: repouso pode agravar, rigidez matinal prolongada, calor e sinovite. Tendências, não critérios absolutos."}, {"slide": 6, "titulo": "Rigidez: tempo e contexto", "explicacao": "Rigidez mecânica breve (cerca de 30 minutos) versus inflamatória prolongada. Perguntas dirigidas sobre o que é travado, tempo e duração."}, {"slide": 7, "titulo": "Artralgia não é artrite", "explicacao": "Artralgia é sintoma subjetivo; artrite é sinal objetivo e palpável. O rubor pode estar ausente."}, {"slide": 8, "titulo": "Distribuição e evolução do acometimento", "explicacao": "Mono (1), oligo (2 a 4) e poliarticular (5 ou mais); axial ou periférico; simétrico ou assimétrico; persistente, aditivo, migratório ou episódico."}, {"slide": 9, "titulo": "Aumento de volume: o que está aumentado", "explicacao": "Derrame, sinovite, bursite, osteófito e edema: cada um com consistência e topografia próprias."}, {"slide": 10, "titulo": "Função: o paciente consegue realizar o movimento?", "explicacao": "Pentear o cabelo, abrir um frasco, levantar de uma cadeira, subir um degrau. Isolar dor, fraqueza verdadeira ou instabilidade."}, {"slide": 11, "titulo": "A queixa articular pode ser sistêmica", "explicacao": "Olhos, boca e intestino, pele e unhas, geniturinário e febre. Sinais sistêmicos mudam a prioridade."}, {"slide": 12, "titulo": "Segurança antes das manobras", "explicacao": "Consentimento, privacidade, começar pelo lado menos doloroso. Trauma com deformidade ou déficit neurovascular: red flag, sem estresse nem testes provocativos."}, {"slide": 13, "titulo": "O método que se repete em cada região", "explicacao": "Inspeção, palpação, mobilidade ativa e passiva, força e testes especiais, nessa ordem."}, {"slide": 14, "titulo": "Palpação: localizar antes de interpretar", "explicacao": "Interlinha, tendão, bursa e êntese; temperatura comparativa; consistência e flutuação."}, {"slide": 15, "titulo": "Mobilidade ativa, passiva e contrarresistência", "explicacao": "Ativa menor que passiva sugere lesão tendínea, fraqueza neurológica ou inibição por dor. Ambas limitadas sugerem componente articular."}, {"slide": 16, "titulo": "Força: paresia ou inibição pela dor", "explicacao": "Escala MRC de 0 a 5. Teste interrompido por dor aguda não classifica o músculo como parético."}, {"slide": 17, "titulo": "Um teste positivo precisa ser descrito", "explicacao": "Sintoma reproduzido, local, fase do movimento e comparação com o lado oposto. Registro vago versus descritivo."}, {"slide": 18, "titulo": "Ombro: exame básico antes dos testes", "explicacao": "Inspeção, palpação (AC, tubérculos úmerais e coracoide) e mobilidade antes das manobras especiais."}, {"slide": 19, "titulo": "Ombro: pesquisa do arco doloroso", "explicacao": "Dor no arco intermediário sugere pinçamento subacromial; no arco final, patologia acromioclavicular."}, {"slide": 20, "titulo": "Manobra de Neer", "explicacao": "Escápula estabilizada, cotovelo estendido, elevação passiva em flexão anterior com leve rotação interna."}, {"slide": 21, "titulo": "Manobra de Hawkins", "explicacao": "Ombro e cotovelo a 90 graus, rotação interna passiva. Nenhum teste isolado tem sensibilidade ou especificidade absolutas."}, {"slide": 23, "titulo": "A sequência precede os epônimos", "explicacao": "Inspeção, palpação, mobilidade, força resistida e só então os testes especiais, guiados pela hipótese."}, {"slide": 24, "titulo": "Teste de Jobe", "explicacao": "Supraespinhoso: 90 graus no plano escapular, polegares para baixo. Dor e fraqueza devem ser registradas separadamente."}, {"slide": 25, "titulo": "Teste de Patte", "explicacao": "Infraespinhoso: rotação externa resistida com ombro e cotovelo a 90 graus. Observar compensação do tronco."}, {"slide": 26, "titulo": "Teste de Gerber", "explicacao": "Subescapular: afastar o dorso da mão da região lombar. Rigidez ou dor intensa torna o teste inconclusivo."}, {"slide": 27, "titulo": "Teste de Speed", "explicacao": "Tendão bicipital: elevação anterior resistida com cotovelo estendido e antebraço supinado; dor focal no sulco bicipital."}, {"slide": 28, "titulo": "Adução cruzada", "explicacao": "Articulação acromioclavicular: dor pontual na AC sustenta a hipótese; dor posterior é alongamento capsular ou muscular."}, {"slide": 29, "titulo": "Síntese: diagnóstico topográfico do ombro", "explicacao": "Estrutura-alvo, teste, sinal clínico e erro comum para supraespinhoso, infraespinhoso, subescapular, bíceps e AC."}, {"slide": 30, "titulo": "Cotovelo: inspeção, palpação e mobilidade", "explicacao": "Epicôndilos e olécrano; flexão de 135 graus e extensão menor que 10 graus; bursa versus articulação."}, {"slide": 31, "titulo": "Teste de Cozen", "explicacao": "Extensão resistida do punho; positivo com dor focal na origem extensora lateral, não no próprio punho."}, {"slide": 32, "titulo": "Flexão resistida do punho", "explicacao": "Origem flexora medial; parestesia no 4º e 5º dedos exige avaliar o nervo ulnar."}, {"slide": 33, "titulo": "Síntese biomecânica: articular versus periarticular", "explicacao": "Limitação simétrica ativa e passiva (articular) versus ativa limitada pela dor com passiva preservada (periarticular)."}, {"slide": 34, "titulo": "Punho e mãos: estrutura e função", "explicacao": "Dorso, palma, unhas, atrofias tenar e hipotenar; pinça, oposição e fechamento."}, {"slide": 35, "titulo": "Mãos: nódulos e tumefação", "explicacao": "Sinovite amolecida (MCF e IFP, inflamatória) versus nódulos duros de Heberden (IFD) e Bouchard (IFP), na osteoartrite."}, {"slide": 36, "titulo": "Checklist crítico: armadilhas semiológicas", "explicacao": "Inibição não é paralisia, rigidez invalida testes, neurologia versus ortopedia e palpação exige contexto."}, {"slide": 37, "titulo": "Punho: teste de Phalen", "explicacao": "Flexão dos punhos por até 60 segundos; parestesia no território mediano. Teste negativo não exclui neuropatia."}, {"slide": 38, "titulo": "Punho: sinal de Tinel", "explicacao": "Percussão leve do mediano na borda radial do tendão palmar longo; positivo com parestesia no território mediano."}, {"slide": 39, "titulo": "De Quervain: técnica e nomenclatura", "explicacao": "Finkelstein é o teste correto; Eichhoff, com polegar aprisionado, tem alta taxa de falso positivo."}, {"slide": 40, "titulo": "Síntese: integrando o ombro doloroso", "explicacao": "Caso de 42 anos: arco intermediário doloroso, passiva livre, Jobe doloroso com força preservada: irritação do manguito, sem provar rotura."}], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Dor ao elevar o braço apenas entre 60 e 120 graus, com mobilidade passiva livre. Qual é a interpretação?", "alternativas": ["Pinçamento subacromial, com dor no arco intermediário", "Lesão acromioclavicular, com dor no arco final extremo", "Artrite glenoumeral, com limitação passiva global", "Radiculopatia cervical, com irradiação ao antebraço", "Capsulite adesiva, com restrição da rotação externa"], "gabarito": "A", "justificativa": "Dor no arco intermediário (60 a 120 graus) sugere pinçamento subacromial; dor no arco final sugere acromioclavicular.", "epônimo": null, "tecnica": "Arco doloroso", "slide": 19}, {"id": 2, "nivel": "muito_dificil", "enunciado": "No teste de Neer, qual é o mecanismo do resultado positivo?", "alternativas": ["Elevação ativa em abdução, com dor no sulco", "Elevação passiva em flexão, com dor habitual", "Compressão do ombro contra o tórax, com dor", "Rotação externa resistida, com cotovelo fletido", "Abdução resistida no plano escapular, com queda"], "gabarito": "B", "justificativa": "Neer: elevação passiva em flexão com leve rotação interna; a dor habitual indica pinçamento subacromial.", "epônimo": null, "tecnica": "Neer", "slide": 20}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Na manobra de Hawkins, qual é a posição inicial e a rotação aplicada?", "alternativas": ["Ombro em extensão, cotovelo estendido, rotação neutra", "Ombro em abdução de 180 graus, com rotação externa ativa", "Ombro e cotovelo a 90°, rotação interna passiva", "Ombro a 45 graus, cotovelo estendido, rotação externa", "Ombro em flexão de 120 graus, com rotação externa"], "gabarito": "C", "justificativa": "Hawkins: ombro e cotovelo a 90 graus com rotação interna passiva; dor subacromial sugere pinçamento.", "epônimo": null, "tecnica": "Hawkins", "slide": 21}, {"id": 4, "nivel": "muito_dificil", "enunciado": "No teste de Jobe, o paciente refere dor e perda da força sustentada. Como registrar?", "alternativas": ["Fraqueza verdadeira do supraespinhoso, com ruptura", "Resultado positivo somente com atrofia visível", "Resultado negativo, pois a dor não interfere no teste", "Dor e força registradas separadamente, sem somar", "Teste invalidado, sem necessidade de registro"], "gabarito": "D", "justificativa": "Dor e incapacidade de sustentar não são a mesma coisa; a inibição dolorosa pode simular paresia.", "epônimo": null, "tecnica": "Jobe", "slide": 24}, {"id": 5, "nivel": "muito_dificil", "enunciado": "No teste de Patte, o tronco do paciente gira durante a rotação externa. O que isso indica?", "alternativas": ["Fraqueza do deltoide, com perda de abdução ativa", "Atrofia do trapézio, com queda do ombro direito", "Lesão do nervo axilar, com parestesia lateral", "Espasticidade cervical, com reflexo exagerado", "Compensação biomecânica que mascara a fraqueza"], "gabarito": "E", "justificativa": "O tronco pode girar para compensar fraqueza ou dor; a compensação deve ser observada e registrada.", "epônimo": null, "tecnica": "Patte", "slide": 25}, {"id": 6, "nivel": "muito_dificil", "enunciado": "No teste de Gerber, o paciente não consegue afastar o dorso da mão das costas. Qual é a interpretação?", "alternativas": ["Teste inconclusivo por rigidez capsular, sem fraqueza", "Fraqueza confirmada do subescapular, sem outras causas", "Lesão do nervo musculocutâneo, com perda sensitiva", "Ruptura do bíceps, com deformidade visível e dor", "Tendinite do supraespinhoso, com dor à abdução"], "gabarito": "A", "justificativa": "Rigidez capsular impede o posicionamento e não equivale à fraqueza; o teste fica inconclusivo.", "epônimo": null, "tecnica": "Gerber", "slide": 26}, {"id": 7, "nivel": "muito_dificil", "enunciado": "No teste de Speed, qual achado é considerado positivo?", "alternativas": ["Desconforto difuso no ombro durante a elevação anterior", "Dor focal ao longo da porção longa do bíceps, no sulco", "Dor na face posterior do ombro à adução cruzada", "Dor à palpação do acrômio com braço em repouso", "Parestesia do quarto e quinto dedos ao elevar o braço"], "gabarito": "B", "justificativa": "Speed é positivo com dor focal na porção longa do bíceps; desconforto difuso não tem o mesmo valor.", "epônimo": null, "tecnica": "Speed", "slide": 27}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Na adução cruzada, dor na face posterior do ombro durante o movimento. O que isso sugere?", "alternativas": ["Lesão acromioclavicular, pela dor posterior do ombro", "Ruptura do supraespinhoso, com perda de força", "Alongamento capsular, sem lesão acromioclavicular", "Compressão medular cervical, com irradiação posterior", "Lesão do subescapular, com fraqueza rotacional"], "gabarito": "C", "justificativa": "Dor pontual na acromioclavicular sustenta a hipótese; dor posterior durante o movimento indica alongamento.", "epônimo": null, "tecnica": "Adução cruzada", "slide": 28}, {"id": 9, "nivel": "muito_dificil", "enunciado": "No teste de Cozen, qual é a manobra e a localização que deve ser reproduzida?", "alternativas": ["Flexão do punho resistida, com dor no epicôndilo medial", "Desvio ulnar resistido, com dor no estiloide radial", "Pronação passiva, com dor no olécrano posterior", "Extensão resistida, com dor no epicôndilo lateral", "Supinação resistida, com dor na fossa cubital"], "gabarito": "D", "justificativa": "Cozen: extensão do punho contra resistência; o positivo reproduz dor focal no epicôndilo lateral.", "epônimo": null, "tecnica": "Cozen", "slide": 31}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Flexão do punho resistida com parestesia no quarto e quinto dedos. Qual é a conduta?", "alternativas": ["Diagnosticar epicondilite medial e tratar localmente", "Descartar a queixa, pois a parestesia é inespecífica", "Infiltrar o epicôndilo medial e reavaliar em duas semanas", "Repouso do punho por quatro semanas, sem exame neurológico", "Avaliar o nervo ulnar, sem rotular como epicondilite"], "gabarito": "E", "justificativa": "Parestesia do quarto e quinto dedos exige avaliação do nervo ulnar; proximidade não justifica epicondilite.", "epônimo": null, "tecnica": "Ulnar", "slide": 32}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Na escala MRC, qual grau é o movimento que vence a gravidade, mas não a resistência do examinador?", "alternativas": ["Grau 3, vence a gravidade, mas não a resistência", "Grau 2, com movimento com gravidade eliminada", "Grau 4, que vence resistência submáxima do examinador", "Grau 1, com contração sem movimento visível", "Grau 5, com força normal em todos os planos musculares"], "gabarito": "A", "justificativa": "Grau 3 vence a gravidade, sem vencer resistência; grau 4 vence resistência submáxima.", "epônimo": null, "tecnica": "MRC", "slide": 16}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Mobilidade ativa limitada e passiva preservada. Qual é a hipótese mais provável?", "alternativas": ["Artrose simétrica, com restrição capsular bilateral", "Lesão tendínea, fraqueza neurológica ou inibição", "Derrame articular volumoso, com limitação global", "Contratura capsular de longa data, com rigidez passiva", "Fratura com desvio, sem alteração da função articular"], "gabarito": "B", "justificativa": "Ativa menor que passiva sugere lesão tendínea, fraqueza neurológica ou inibição dolorosa.", "epônimo": null, "tecnica": "Mobilidade", "slide": 15}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Articulação dolorosa sem rubor. O que se conclui?", "alternativas": ["Artrite afastada, pois o rubor é sinal obrigatório", "Artralgia confirmada, pela ausência de vermelhidão", "Artrite não afastada, pois o rubor pode estar ausente", "Bursite confirmada, pela ausência de calor e rubor", "Lesão neurológica confirmada, sem inflamação articular"], "gabarito": "C", "justificativa": "O rubor pode estar ausente na artrite profunda; não se deve depender da vermelhidão para diagnosticar artrite.", "epônimo": null, "tecnica": "Artralgia x artrite", "slide": 7}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Nódulos rígidos e duros de interfalângicas distais, sem sinovite. Qual é a interpretação?", "alternativas": ["Sinovite inflamatória, pela consistência amolecida", "Bursite de tendão flexor, pela localização distal", "Derrame articular de origem infecciosa, com febre", "Proliferação óssea, compatível com osteoartrite", "Edema subcutâneo gravitacional, com sinal do cacifo"], "gabarito": "D", "justificativa": "Nódulos duros são proliferação óssea (Heberden, na interfalângica distal); a sinovite é amolecida.", "epônimo": null, "tecnica": "Heberden", "slide": 35}, {"id": 15, "nivel": "muito_dificil", "enunciado": "No teste de Phalen, qual é a manobra e o tempo recomendado?", "alternativas": ["Extensão dos punhos por cinco minutos, com dor ulnar", "Rotação do antebraço por trinta segundos, com dor no cotovelo", "Pressão local sobre o túnel por dez segundos, com dor", "Desvio radial por dois minutos, com edema dorsal", "Flexão dos punhos por até 60 segundos, com parestesia"], "gabarito": "E", "justificativa": "Phalen mantém a flexão dos punhos por até 60 segundos; a parestesia mediana é o achado positivo.", "epônimo": null, "tecnica": "Phalen", "slide": 37}], "casos_extremos": [{"titulo": "Caso W1 · Ombro doloroso com múltiplas manobras", "texto": "Homem de 44 anos, pintor, refere dor ao elevar o braço direito entre 70 e 110 graus há 3 meses, sem irradiação. Mobilidade passiva livre. Jobe com dor e força preservada. Neer positivo com dor habitual. Speed com dor difusa no ombro, sem foco no sulco bicipital. Hawkins positivo.", "perguntas": [{"pergunta": "Qual é a interpretação topográfica do quadro?", "alternativas": ["Ruptura completa do supraespinhoso, pela dor e pelo Jobe positivo", "Irritação do manguito por pinçamento subacromial, sem prova de ruptura", "Tendinite do bíceps, pelo Speed positivo com dor difusa", "Artrose glenoumeral avançada, pela mobilidade passiva livre", "Lesão acromioclavicular, pela dor no arco final da elevação"], "gabarito": "B", "justificativa": "Dor no arco intermediário com Neer e Hawkins positivos e força preservada sugere pinçamento; o Speed sem dor focal não é positivo."}, {"pergunta": "Qual é o erro de registro que deve ser evitado neste exame?", "alternativas": ["Registrar dor e força separadamente para o teste de Jobe", "Interpretar dor difusa no ombro como positividade do Speed", "Descrever a fase do movimento em que a dor aparece no exame", "Comparar o achado com o lado oposto do mesmo paciente", "Registrar a mobilidade passiva separadamente da ativa do ombro"], "gabarito": "B", "justificativa": "O Speed é positivo apenas com dor focal no sulco bicipital; dor difusa não deve ser interpretada como positividade."}]}, {"titulo": "Caso W2 · Cotovelo e nervo ulnar", "texto": "Mulher de 55 anos, digitadora, refere dor no lado lateral do cotovelo direito e parestesia no quarto e quinto dedos há 4 meses, mais intensa à noite. Cozen positivo com dor focal no epicôndilo lateral. Flexão do punho resistida com parestesia irradiada para os dedos mínimo e anular. Força preservada.", "perguntas": [{"pergunta": "Qual é a interpretação correta dos dois achados?", "alternativas": ["Epicondilite lateral isolada, com parestesia por compressão local", "Epicondilite lateral coexistente com acometimento do nervo ulnar", "Síndrome do túnel do carpo, pela parestesia dos dedos", "Radiculopatia C6, pelo teste de Cozen positivo", "Lesão do nervo radial, pela dor no lado lateral do cotovelo"], "gabarito": "B", "justificativa": "Dor focal no epicôndilo lateral sustenta epicondilite; parestesia do quarto e quinto dedos exige avaliação do nervo ulnar, sem rotular como epicondilite."}, {"pergunta": "Qual é a conduta de investigação mais adequada para o nervo ulnar?", "alternativas": ["Infiltrar o epicôndilo lateral e reavaliar em duas semanas", "Exame neurológico dirigido ao nervo ulnar e considerar eletroneuromiografia", "Repouso do punho por quatro semanas, sem nenhum exame neurológico", "Órtese de punho noturna e alta sem avaliação neurológica", "Descartar a queixa, pois a parestesia costuma ser inespecífica"], "gabarito": "B", "justificativa": "A suspeita de neuropatia ulnar exige exame neurológico dirigido e, quando indicado, eletroneuromiografia."}]}, {"titulo": "Caso W3 · Punho doloroso e parestesia noturna", "texto": "Homem de 48 anos, com diabetes tipo 2, apresenta parestesia noturna no polegar, indicador e médio bilateral, com dor no lado radial do punho direito ao segurar objetos. Phalen positivo aos 40 segundos com parestesia mediana. Finkelstein positivo. O teste de Eichhoff, feito com o polegar preso, resultou positivo.", "perguntas": [{"pergunta": "Qual é a interpretação mais precisa dos achados?", "alternativas": ["Tenossinovite de De Quervain confirmada pelo teste de Eichhoff", "Neuropatia mediana, com Phalen positivo, e possível De Quervain com Finkelstein", "Radiculopatia C6 bilateral, pela parestesia dos dedos radiais", "Artrite reumatoide do punho, pela dor no lado radial do punho", "Lesão do nervo ulnar, pelo território dos dedos mínimo e anular"], "gabarito": "B", "justificativa": "Phalen positivo com parestesia mediana sugere síndrome do túnel do carpo; o Finkelstein é o teste correto para De Quervain, e o Eichhoff é erro comum."}, {"pergunta": "Qual é o erro técnico que invalida a interpretação do Eichhoff neste caso?", "alternativas": ["Manter o polegar aprisionado, o que gera falsa positividade", "Realizar o teste com o punho em extensão, sem desvio ulnar", "Usar o tempo de sessenta segundos para a manobra de flexão", "Examinar apenas o lado esquerdo, sem comparação bilateral", "Registrar o resultado sem descrever a localização da dor"], "gabarito": "A", "justificativa": "O Eichhoff, com polegar aprisionado, é erro comum e tem alta taxa de falso positivo; o Finkelstein deve ser o teste utilizado."}]}]};
